// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import {
    createCollection,
    createLink,
    createHighlight,
    getHighlights,
    updateHighlight,
    updateHighlightMethodNotAllowed,
    deleteCollection,
} from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Declaration of variables
    const take = "abc";

    // Request Body
    const collectionsPostRequestBody: string = `{
        "color": "#0ea5e9",
        "description": "",
        "name": "Highlights Rejections"
    }`;

    const collectionsPostResponse = await createCollection(client, headers, collectionsPostRequestBody);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("Highlights Rejections");
    expect(getResponseValue(collectionsPostResponse, "response.color"), 'color').toBe("#0ea5e9");
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'id').toBeGreaterThan(0);

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "id": 7101
        },
        "description": "",
        "name": "Rejections Source",
        "tags": [],
        "type": "url",
        "url": "https://example.com/rejections"
    }`;

    const linksPostResponse = await createLink(
        client,
        headers,
        linksPostRequestBody,
        {"collection.id": getResponseValue(collectionsPostResponse, "response.id")}
    );
    expect(linksPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("Rejections Source");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("https://example.com/rejections");
    expect(getResponseValue(linksPostResponse, "response.collectionId"), 'collectionId').toBe(getResponseValue(collectionsPostResponse, "response.id"));
    expect(getResponseValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);

    // Request Body
    const highlightsPostRequestBody: string = `{
        "color": "purple",
        "endOffset": 15,
        "linkId": 7202,
        "startOffset": 0,
        "text": "Rejected colour"
    }`;

    const highlightsPostResponse = await createHighlight(
        client,
        headers,
        highlightsPostRequestBody,
        {"linkId": getResponseValue(linksPostResponse, "response.id")},
        400
    );
    expect(highlightsPostResponse.statusCode, 'status code').toBe(400);

    expect(getResponseValue(highlightsPostResponse, "response"), 'colour outside the four is named in the error').toBe("Error: Invalid option: expected one of \"yellow\"|\"green\"|\"blue\"|\"red\" [color]");
    expect(getResponseValue(highlightsPostResponse, "response.id"), 'no highlight was created').toBeNull();

    // Request Body
    const highlightsPost1RequestBody: string = `{
        "color": "yellow",
        "comment": "rejections note",
        "endOffset": 15,
        "linkId": 7202,
        "startOffset": 0,
        "text": "Rejected colour"
    }`;

    const highlightsPost1Response = await createHighlight(
        client,
        headers,
        highlightsPost1RequestBody,
        {"linkId": getResponseValue(linksPostResponse, "response.id")}
    );
    expect(highlightsPost1Response.statusCode, 'status code').toBe(200);

    // The same request with an allowed colour succeeds, so the refusal above is about the colour alone.
    expect(getResponseValue(highlightsPost1Response, "response.color"), 'color').toBe("yellow");
    expect(getResponseValue(highlightsPost1Response, "response.comment"), 'comment').toBe("rejections note");
    expect(getResponseValue(highlightsPost1Response, "response.text"), 'text').toBe("Rejected colour");
    expect(getResponseValue(highlightsPost1Response, "response.linkId"), 'linkId').toBe(getResponseValue(linksPostResponse, "response.id"));
    expect(getResponseValue(highlightsPost1Response, "response.id"), 'id').toBeGreaterThan(0);

    const highlightsGetResponse = await getHighlights(client, headers, {"color": ["purple"]}, 400);
    expect(highlightsGetResponse.statusCode, 'status code').toBe(400);

    expect(getResponseValue(highlightsGetResponse, "response"), 'colour filter error names the four allowed colours').toBe("Invalid color. Allowed colors are: yellow, green, blue, red.");
    expect(getResponseValue(highlightsGetResponse, "response.highlights"), 'no page is returned').toBeNull();

    const highlightsGet1Response = await getHighlights(client, headers, {"take": ["0"]}, 400);
    expect(highlightsGet1Response.statusCode, 'status code').toBe(400);

    expect(getResponseValue(highlightsGet1Response, "response"), 'take below the range is refused by name').toBe("take must be a whole number between 1 and 100.");
    expect(getResponseValue(highlightsGet1Response, "response.highlights"), 'no page is returned').toBeNull();

    const highlightsGet2Response = await getHighlights(client, headers, {"take": [take]}, 400);
    expect(highlightsGet2Response.statusCode, 'status code').toBe(400);

    expect(getResponseValue(highlightsGet2Response, "response"), 'non-numeric take is refused by name').toBe("take must be a whole number between 1 and 100.");
    expect(getResponseValue(highlightsGet2Response, "response.highlights"), 'no page is returned').toBeNull();

    const highlightsGet3Response = await getHighlights(client, headers, {"cursor": [take]}, 400);
    expect(highlightsGet3Response.statusCode, 'status code').toBe(400);

    expect(getResponseValue(highlightsGet3Response, "response"), 'non-numeric cursor is refused by name').toBe("cursor must be the id of a highlight.");
    expect(getResponseValue(highlightsGet3Response, "response.highlights"), 'no page is returned').toBeNull();

    // Request Body
    const highlightsHighlightsPatchRequestBody: string = `{
        "text": "not an updatable field"
    }`;

    const highlightsHighlightsPatchResponse = await updateHighlight(
        client,
        headers,
        highlightsHighlightsPatchRequestBody,
        getResponseValue(highlightsPost1Response, "response.id"),
        400
    );
    expect(highlightsHighlightsPatchResponse.statusCode, 'status code').toBe(400);

    expect(getResponseValue(highlightsHighlightsPatchResponse, "response"), 'a body with neither colour nor comment has nothing to update').toBe("Error: Provide a color or a comment to update []");
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.id"), 'nothing was updated').toBeNull();

    // Request Body
    const highlightsHighlightsPatch1RequestBody: string = `{
        "color": "purple"
    }`;

    const highlightsHighlightsPatch1Response = await updateHighlight(
        client,
        headers,
        highlightsHighlightsPatch1RequestBody,
        getResponseValue(highlightsPost1Response, "response.id"),
        400
    );
    expect(highlightsHighlightsPatch1Response.statusCode, 'status code').toBe(400);

    expect(getResponseValue(highlightsHighlightsPatch1Response, "response"), 'PATCH refuses a colour outside the four by name').toBe("Error: Invalid option: expected one of \"yellow\"|\"green\"|\"blue\"|\"red\" [color]");
    expect(getResponseValue(highlightsHighlightsPatch1Response, "response.id"), 'nothing was updated').toBeNull();

    // Request Body
    const highlightsPutRequestBody: string = `{
        "color": "yellow"
    }`;

    const highlightsPutResponse = await updateHighlightMethodNotAllowed(client, headers, highlightsPutRequestBody);
    expect(highlightsPutResponse.statusCode, 'status code').toBe(405);

    expect(getResponseValue(highlightsPutResponse, "response"), 'an unhandled method is named, not silently dropped').toBe("Method not allowed.");

    const collectionsCollectionsDeleteResponse = await deleteCollection(
        client,
        headers,
        getResponseValue(collectionsPostResponse, "response.id")
    );
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'deleted collection id').toBe(getResponseValue(collectionsPostResponse, "response.id"));
});
